  'Find patterns and possibilities': { ta: 'வடிவங்களையும் சாத்தியங்களையும் கண்டறியுங்கள்', te: 'నమూనాలు, అవకాశాలను కనుగొనండి', hi: 'पैटर्न और संभावनाएँ खोजें' },
  'Tell us what you want to learn': { ta: 'நீங்கள் கற்க விரும்புவதைச் சொல்லுங்கள்', te: 'మీరు నేర్చుకోవాలనుకున్నది చెప్పండి', hi: 'हमें बताएँ कि आप क्या सीखना चाहती हैं' },
  'Not yet': { ta: 'இன்னும் இல்லை', te: 'ఇంకా కాదు', hi: 'अभी नहीं' }, 'A little': { ta: 'சிறிதளவு', te: 'కొద్దిగా', hi: 'थोड़ा' }, 'Getting there': { ta: 'முன்னேறுகிறேன்', te: 'అక్కడికి చేరుతున్నాను', hi: 'वहाँ पहुँच रही हूँ' }, 'Mostly': { ta: 'பெரும்பாலும்', te: 'ఎక్కువగా', hi: 'अधिकतर' }, 'Absolutely': { ta: 'மிகவும்', te: 'ఖచ్చితంగా', hi: 'बिलकुल' },
