const copyFor = (value, language = 'en') => {
  if (language === 'en' || !value) return value
  const key = pageCopy[value] ? value : Object.keys(pageCopy).find((item) => item.toLocaleLowerCase() === String(value).toLocaleLowerCase())
  return pageCopy[key]?.[language] || value
}
const localeReverse = Object.fromEntries(Object.entries(pageCopy).flatMap(([english, translations]) => Object.values(translations).map((translation) => [translation, english])))
const localePatterns = {
  ta: { question: 'கேள்வி', saved: 'சேமிக்கப்பட்டது', opportunity: 'வாய்ப்பு', opportunities: 'வாய்ப்புகள்', profile: 'சுயவிவரம் புரிந்தது', sources: 'மூலம் பகுப்பாய்வு செய்யப்பட்டது', source: 'மூலம் பகுப்பாய்வு செய்யப்பட்டது', signals: 'சுயவிவர அறிகுறிகள் வழங்கப்பட்டன', day: 'நாள்', week: 'வாரம்', month: 'நாட்கள்', year: 'ஆண்டு' },
  te: { question: 'ప్రశ్న', saved: 'సేవ్ చేయబడింది', opportunity: 'అవకాశం', opportunities: 'అవకాశాలు', profile: 'ప్రొఫైల్ అర్థమైంది', sources: 'మూలాలు విశ్లేషించబడ్డాయి', source: 'మూలం విశ్లేషించబడింది', signals: 'ప్రొఫైల్ సంకేతాలు అందించబడ్డాయి', day: 'రోజు', week: 'వారం', month: 'రోజులు', year: 'సంవత్సరం' },
  hi: { question: 'प्रश्न', saved: 'सहेजा गया', opportunity: 'अवसर', opportunities: 'अवसर', profile: 'प्रोफ़ाइल समझी गई', sources: 'स्रोतों का विश्लेषण हुआ', source: 'स्रोत का विश्लेषण हुआ', signals: 'प्रोफ़ाइल संकेत दिए गए', day: 'दिन', week: 'सप्ताह', month: 'दिन', year: 'वर्ष' },
}
const localizePattern = (raw, language) => {
  if (language === 'en') return raw
  const words = localePatterns[language] || localePatterns.ta
  let match = raw.match(/^Question (\d+) of (\d+)$/i)
  if (match) return `${words.question} ${match[1]} / ${match[2]}`
  match = raw.match(/^QUESTION (\d+) OF (\d+)$/)
  if (match) return `${words.question} ${match[1]} / ${match[2]}`
  match = raw.match(/^(\d+) saved$/i)
  if (match) return `${match[1]} ${words.saved}`
  match = raw.match(/^(\d+) opportunity saved$/i)
  if (match) return `${match[1]} ${words.opportunity} ${words.saved}`
  match = raw.match(/^(\d+) opportunities saved$/i)
  if (match) return `${match[1]} ${words.opportunities} ${words.saved}`
  match = raw.match(/^(\d+) sources analysed$/i)
  if (match) return `${match[1]} ${words.sources}`
  match = raw.match(/^1 source analysed$/i)
  if (match) return `1 ${words.source}`
  match = raw.match(/^1 day$/i)
  if (match) return `1 ${words.day}`
  match = raw.match(/^1 week$/i)
  if (match) return `1 ${words.week}`
  match = raw.match(/^30 days$/i)
  if (match) return `30 ${words.month}`
  match = raw.match(/^1 year$/i)
  if (match) return `1 ${words.year}`
  return raw
}
const localizeVisibleText = (value, language) => {
  if (!value) return value
  // Vite/devtools may inject very large text nodes into the app root. They are
  // not interface copy, so leave them untouched instead of processing them.
  if (value.length > 500) return value
  const leading = value.match(/^\s*/)?.[0] || ''; const trailing = value.match(/\s*$/)?.[0] || ''
  const raw = value.trim(); const patterned = localizePattern(raw, language)
  if (patterned !== raw) return `${leading}${patterned}${trailing}`
  const english = localeReverse[raw] || raw
  const source = pageCopy[english] ? english : Object.keys(pageCopy).find((key) => key.toLocaleLowerCase() === english.toLocaleLowerCase()) || english
  return `${leading}${language === 'en' ? source : pageCopy[source]?.[language] || raw}${trailing}`
}

function useRoute() {
  const current = () => location.hash.replace('#/', '') || 'home'
  const [route, setRoute] = useState(current)
  useEffect(() => { const watch = () => setRoute(current()); addEventListener('hashchange', watch); return () => removeEventListener('hashchange', watch) }, [])
  const go = (next) => { location.hash = `#/${next}` }
  return [route, go]
}

