function MatchResults({ data, chosen, onReset, go, saved = [], onSave, reentry = false }) {
  const primary = data.recommendations?.[0]
  const [saving, setSaving] = useState(false)
  const [notice, setNotice] = useState('')
  if (!primary) return <section className="compact-report glass"><h2>No pathway could be ranked yet.</h2><Button onClick={onReset}>Try again</Button></section>
  const freshness = primary.skillFreshness || { retained: [], rusty: [], missing: primary.missing || [] }
  const isSaved = saved.some((item) => `${item.category}:${item.title}` === `${chosen?.key}:${primary.title}`)
  const save = async () => { if (!onSave) return; setSaving(true); try { await onSave(chosen.key, primary); setNotice('Saved to your shortlist.') } catch { setNotice('Could not save this pathway. Please try again.') } finally { setSaving(false) } }
  return <section className="compact-report"><header className="compact-hero glass"><div><span className="badge"><ShieldCheck size={13}/> FOUR RULE-BASED CHECKS</span><h1>{reentry ? 'Your shortest realistic return path.' : 'Your practical next move.'}</h1><p>{data.profileSummary}</p><small className="dataset-note"><Code2 size={13}/> {data.dataset?.records || 34} synthetic pathways ranked for this profile</small></div><div className="compact-score"><b>{primary.readiness}%</b><span>ROLE MATCH</span></div></header><p className="compact-note"><CircleHelp size={15}/>{data.advisorNote}</p><div className="compact-pipeline">{data.pipeline?.map((item, index) => <span key={item.agent}><b>{index + 1}</b>{item.agent}</span>)}</div><div className="compact-grid"><article className="compact-card glass"><p className="eyebrow">SKILL FRESHNESS</p><h2>What you already bring</h2><SkillGroup label="Retained" tone="retained" skills={freshness.retained}/><SkillGroup label="Rusty / refresh" tone="rusty" skills={freshness.rusty}/><SkillGroup label="Missing" tone="missing" skills={freshness.missing}/></article><article className="compact-card glass"><p className="eyebrow">BEST-FIT ROLE</p><h2>{primary.title}</h2><p>{primary.description || primary.details}</p><OpportunityMeta item={primary}/><div className="score-lines">{Object.entries(primary.scoreBreakdown || {}).map(([label, value]) => <div key={label}><span>{label}<b>{value}%</b></span><i><em style={{ width: `${value}%` }}/></i></div>)}</div><p className="eligibility-copy"><ShieldCheck size={15}/>{primary.eligibility}</p><div className="next-action"><Rocket size={18}/><div><small>NEXT ACTION</small><b>{primary.nextBestStep}</b></div></div>{onSave && <Button variant="ghost" onClick={save} disabled={saving || isSaved} icon={isSaved ? BookmarkCheck : Bookmark}>{isSaved ? 'Saved' : saving ? 'Saving…' : 'Save pathway'}</Button>}</article></div>{data.recommendations?.length > 1 && <section className="compact-section generated-options"><div className="compact-section-head"><div><p className="eyebrow">OTHER GENERATED PATHWAYS</p><h2>Different routes, same honest match</h2></div><p>Every card comes from a different synthetic opportunity record and is ranked against the same answers.</p></div><div className="generated-option-grid">{data.recommendations.slice(1).map((item) => <article className="generated-option glass" key={item.title}><div><span className="match-percent">{item.match}</span><span className="match-label"> MATCH</span></div><h3>{item.title}</h3><p>{item.description || item.reason}</p><OpportunityMeta item={item}/><small>{item.nextBestStep}</small></article>)}</div></section>}{reentry && <><section className="compact-section"><div className="compact-section-head"><div><p className="eyebrow">REVERSE INTERNSHIP / RETURNSHIP</p><h2>Supported routes that use your existing skills</h2></div><p>Short, re-entry-friendly opportunities ranked by skill and stated work fit.</p></div><div className="returnship-list">{(data.returnships || []).map((item) => <article className="returnship-card glass" key={item.title}><span>{item.match} match</span><h3>{item.title}</h3><p>{item.description || item.details}</p><OpportunityMeta item={item}/><small>{item.why}</small><em>{item.flexibility?.explanation}</em></article>)}</div></section><section className="compact-section"><div className="compact-section-head"><div><p className="eyebrow">RE-ENTRY ROADMAP</p><h2>Only the next steps that matter</h2></div></div><div className="short-roadmap">{primary.roadmap?.map((step, index) => <article key={step.stage}><b>{index + 1}</b><div><span>{step.duration}</span><h3>{step.stage}</h3><p>{step.task}</p></div></article>)}</div></section><section className="progress-dashboard glass"><div><div><p className="eyebrow">RE-ENTRY PROGRESS</p><h2>Skills → Projects → Funding → Returnship → Applications → Employment</h2></div><div className="progress-status"><b>{data.progress?.completed || 0}/6</b><span>complete</span></div></div><div className="progress-steps">{data.progress?.steps?.map((step) => <article className={step.complete ? 'done' : step.name === data.progress?.current ? 'current' : step.notRequired ? 'optional' : ''} key={step.name}><i>{step.complete ? <Check size={13}/> : step.notRequired ? '–' : ''}</i><b>{step.name}</b><small>{step.detail}</small></article>)}</div><p className="progress-next"><Target size={17}/><b>Recommended next action:</b> {data.progress?.recommendedNextAction}</p></section></>}<section className="compact-section"><div className="compact-section-head"><div><p className="eyebrow">OTHER REALISTIC OPTION</p><h2>{data.recommendations?.[1]?.title || 'Keep building current evidence'}</h2></div><p>{data.recommendations?.[1]?.reason || 'A focused project will make your strongest option even clearer.'}</p></div></section>{notice && <p className="save-note" role="status">{notice}</p>}<footer className="compact-footer"><button className="back" onClick={onReset}>Start a new analysis</button>{go && <Button variant="ghost" onClick={() => go('impact')} icon={BarChart3}>See impact</Button>}</footer></section>
}

function WorkFund({ go, saved, onSave, user, language = 'en' }) {
  const [chosen, setChosen] = useState(null); const [data, setData] = useState(null); const [loading, setLoading] = useState(false); const [error, setError] = useState('')
  const analyse = async (profile) => { setLoading(true); setError(''); try { setData(await api.matches(chosen.key, profile)) } catch { setError('The matching service could not complete the analysis. Please check the backend and try again.') } finally { setLoading(false) } }
  const reset = () => { setChosen(null); setData(null); setError('') }
  return <div className="page flow-page career-page"><div className="work-heading"><FlowHeader icon={BriefcaseBusiness} kicker="WORK & FUND" title="A practical next move, not a long report." text="Six concise signals identify your skills, work fit and shortest next step."/>{saved.length > 0 && <button onClick={() => go('saved')} className="saved-shortcut"><Bookmark size={16}/><span>{saved.length} saved</span></button>}</div>{error && <p className="service-error glass" role="alert">{error}</p>}{!chosen && <section className="work-options upgraded-options">{workOptions.map((option, i) => <motion.button key={option.key} className="work-option glass tilt-card" onClick={() => setChosen(option)} initial={{opacity:0,y:18}} animate={{opacity:1,y:0}} transition={{delay:i*.07}}><span className="work-icon"><option.icon size={25}/></span><span className="agent-label"><Bot size={13}/> 34-record catalog</span><h3>{option.title}</h3><p>{option.copy}</p><span className="work-cta">Build my profile <ArrowRight size={16}/></span></motion.button>)}</section>}{chosen && !data && <ProfileIntake questions={workProfileQuestions} user={user} agentName={chosen.agent} intro={`Let’s find your ${chosen.title.toLowerCase()}.`} onSubmit={analyse} onCancel={reset} loading={loading}/>} {data && <MatchResults data={data} chosen={chosen} onReset={reset} go={go} saved={saved} onSave={onSave}/>}</div>
}

function RestartGrow({ go, user, language = 'en' }) {
  const [result, setResult] = useState(null); const [loading, setLoading] = useState(false); const [error, setError] = useState('')
  const analyse = async (profile) => { setLoading(true); setError(''); try { setResult(await api.strengths(profile)) } catch { setError('The Career Re-entry analysis could not be completed. Please check the backend and try again.') } finally { setLoading(false) } }
  return <div className="page flow-page career-page"><FlowHeader icon={HeartHandshake} kicker="CAREER RE-ENTRY" title="You are returning, not starting over." text="StemPulse keeps what you already have, shows what needs refreshing, and maps the shortest realistic route to work."/>{error && <p className="service-error glass" role="alert">{error}</p>}{!result ? <ProfileIntake questions={reentryProfileQuestions} user={user} agentName="Career Re-entry Agent" intro="Let’s turn your earlier experience into a current, practical path." onSubmit={analyse} onCancel={() => go('home')} loading={loading}/> : <MatchResults data={result} chosen={{key:'jobs'}} onReset={() => setResult(null)} go={go} reentry/>}</div>
}

function LegacyImpactDashboard({ metrics }) {
  const tiles = [ ['👩‍💻', 'Women onboarded', metrics.womenOnboarded, 'womenOnboarded'], ['🎓', 'Girls/Women exploring STEM', metrics.exploringStem, 'exploringStem'], ['🔄', 'Women returning to STEM', metrics.returningStem, 'returningStem'], ['💼', 'Opportunities discovered', metrics.opportunities, 'opportunities'], ['🎯', 'Opportunity matches', metrics.matches, 'matches'], ['🛣️', 'Career roadmaps generated', metrics.roadmaps, 'roadmaps'], ['📈', 'Skills upgraded', metrics.skillsUpgraded, 'skillsUpgraded'], ['🤝', 'Successful STEM re-entries', metrics.reentries, 'reentries'] ]
  const journeys = [{name:'Learn & Enter', value:metrics.exploringStem}, {name:'Work & Fund', value:Math.round(metrics.matches*.47)}, {name:'Restart & Grow', value:metrics.returningStem}]
  const fields = [{name:'Data & AI', value:35},{name:'Web & Product', value:24},{name:'Cyber', value:16},{name:'Engineering', value:25}]
  const opportunity = [{name:'Jobs', value:42},{name:'Internships', value:25},{name:'Scholarships', value:19},{name:'Funding', value:14}]
  const completion = [{name:'Start', value:100},{name:'First step', value:81},{name:'Build', value:62},{name:'Finish', value:47}]
  const skillsData = [{name:'Coordination', value:91},{name:'Resources',value:88},{name:'Planning',value:86},{name:'Data organisation',value:82},{name:'Optimisation',value:79}]
  const growth = [{month:'Apr',women:6700},{month:'May',women:7900},{month:'Jun',women:9100},{month:'Jul',women:10400},{month:'Aug',women:11700},{month:'Now',women:metrics.womenOnboarded}]
  return <div className="page dashboard-page"><section className="dashboard-hero"><div><p className="eyebrow"><span className="live-dot"/> LIVE IMPACT DASHBOARD</p><h1>Every action expands <em>her horizon.</em></h1><p>Watch StemPulse ripple in real time. Generate a roadmap, find a match or reveal strengths — the numbers move live.</p></div><div className="live-badge glass"><span className="ping"/> Connected to StemPulse live events</div></section><section className="metric-grid">{tiles.map(([emoji, label, value, key],i)=><motion.article className="metric-card glass" key={key} initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:i*.04}}><span className="metric-emoji">{emoji}</span><div><strong>{IN(value)}</strong><p>{label}</p></div><span className="metric-glow"/></motion.article>)}</section><section className="chart-grid"><ChartCard title="Women across every journey" subtitle="Where women are choosing to grow"><ResponsiveContainer width="100%" height={235}><BarChart data={journeys} margin={{top:10,left:-18,right:10}}><XAxis dataKey="name" tick={{fontSize:11,fill:'#765464'}} axisLine={false} tickLine={false}/><YAxis tick={{fontSize:11,fill:'#765464'}} axisLine={false} tickLine={false}/><Tooltip contentStyle={tooltipStyle}/><Bar dataKey="value" radius={[10,10,0,0]}>{journeys.map((_,i)=><Cell key={i} fill={colors[i]}/>)}</Bar></BarChart></ResponsiveContainer></ChartCard><ChartCard title="STEM fields explored" subtitle="A beautifully broad curiosity"><ResponsiveContainer width="100%" height={235}><PieChart><Pie data={fields} dataKey="value" nameKey="name" innerRadius={54} outerRadius={83} paddingAngle={4}>{fields.map((_,i)=><Cell fill={colors[i]} key={i}/>)}</Pie><Tooltip contentStyle={tooltipStyle}/></PieChart></ResponsiveContainer><div className="chart-key">{fields.map((x,i)=><span key={x.name}><i style={{background:colors[i]}}/>{x.name}</span>)}</div></ChartCard><ChartCard title="Opportunity distribution" subtitle="More pathways, more choice"><ResponsiveContainer width="100%" height={235}><BarChart data={opportunity} layout="vertical" margin={{left:24,right:10}}><XAxis type="number" hide/><YAxis type="category" dataKey="name" tick={{fontSize:11,fill:'#765464'}} width={78} axisLine={false} tickLine={false}/><Tooltip contentStyle={tooltipStyle}/><Bar dataKey="value" fill="#c74b7c" radius={[0,8,8,0]}/></BarChart></ResponsiveContainer></ChartCard><ChartCard title="Roadmap completion" subtitle="Progress over perfection"><ResponsiveContainer width="100%" height={235}><AreaChart data={completion} margin={{top:10,left:-18,right:10}}><defs><linearGradient id="roadGrad" x1="0" x2="0" y1="0" y2="1"><stop stopColor="#c74b7c" stopOpacity=".52"/><stop offset="1" stopColor="#c74b7c" stopOpacity="0"/></linearGradient></defs><XAxis dataKey="name" tick={{fontSize:11,fill:'#765464'}} axisLine={false} tickLine={false}/><YAxis tick={{fontSize:11,fill:'#765464'}} axisLine={false} tickLine={false}/><Tooltip contentStyle={tooltipStyle}/><Area type="monotone" dataKey="value" stroke="#8b2349" strokeWidth={3} fill="url(#roadGrad)"/></AreaChart></ResponsiveContainer></ChartCard><ChartCard title="Restart & Grow transferable skills" subtitle="Lived experience made visible" wide><ResponsiveContainer width="100%" height={250}><BarChart data={skillsData} margin={{top:15,left:-20,right:10}}><XAxis dataKey="name" tick={{fontSize:10,fill:'#765464'}} axisLine={false} tickLine={false}/><YAxis domain={[0,100]} tick={{fontSize:11,fill:'#765464'}} axisLine={false} tickLine={false}/><Tooltip contentStyle={tooltipStyle}/><Bar dataKey="value" fill="#efc56e" radius={[10,10,0,0]}/></BarChart></ResponsiveContainer></ChartCard><ChartCard title="Women participation growth" subtitle="A rising collective signal" wide><ResponsiveContainer width="100%" height={250}><AreaChart data={growth} margin={{top:10,left:-18,right:10}}><defs><linearGradient id="growthGrad" x1="0" x2="0" y1="0" y2="1"><stop stopColor="#7e2146" stopOpacity=".5"/><stop offset="1" stopColor="#7e2146" stopOpacity="0"/></linearGradient></defs><XAxis dataKey="month" tick={{fontSize:11,fill:'#765464'}} axisLine={false} tickLine={false}/><YAxis tick={{fontSize:11,fill:'#765464'}} axisLine={false} tickLine={false}/><Tooltip contentStyle={tooltipStyle}/><Area type="monotone" dataKey="women" stroke="#7e2146" strokeWidth={3} fill="url(#growthGrad)"/></AreaChart></ResponsiveContainer></ChartCard></section></div>
}
function ImpactDashboardCore({ metrics, language }) {
  const [window, setWindow] = useState('7d')
  const [timeline, setTimeline] = useState(null)
  const [loading, setLoading] = useState(true)
  useEffect(() => {
    let active = true
    setLoading(true)
    api.impactTimeline(window).then((data) => { if (active) setTimeline(data) }).catch(() => { if (active) setTimeline({ metrics: { opportunities: 0, skillsUpgraded: 0, roadmaps: 0, matches: 0, exploringStem: 0 }, comparisons: [] }) }).finally(() => active && setLoading(false))
    return () => { active = false }
  }, [window, metrics])
  const value = timeline?.metrics || {}
  const labels = window === '1d' ? t(language, 'day') : window === '7d' ? t(language, 'week') : window === '30d' ? t(language, 'month') : t(language, 'year')
  const tiles = [
    { icon: BriefcaseBusiness, label: language === 'en' ? 'Opportunities discovered' : language === 'ta' ? 'கண்டறிந்த வாய்ப்புகள்' : language === 'te' ? 'కనుగొన్న అవకాశాలు' : 'खोजे गए अवसर', value: value.opportunities || 0, color: '#c74b7c' },
    { icon: GraduationCap, label: language === 'en' ? 'Learning actions' : language === 'ta' ? 'கற்றல் செயல்கள்' : language === 'te' ? 'అభ్యాస చర్యలు' : 'सीखने की गतिविधियाँ', value: (value.skillsUpgraded || 0) + (value.roadmaps || 0), color: '#7e2146' },
    { icon: MessageCircleHeart, label: language === 'en' ? 'Mentor & opportunity matches' : language === 'ta' ? 'வழிகாட்டி மற்றும் வாய்ப்பு பொருத்தங்கள்' : language === 'te' ? 'మెంటర్, అవకాశం సరిపోలికలు' : 'मेंटर और अवसर मिलान', value: value.matches || 0, color: '#efc56e' },
    { icon: Users, label: language === 'en' ? 'Women exploring STEM' : language === 'ta' ? 'STEM ஆராயும் பெண்கள்' : language === 'te' ? 'STEM అన్వేషిస్తున్న మహిళలు' : 'STEM खोजती महिलाएँ', value: value.exploringStem || 0, color: '#8b6477' },
  ]
  return <div className="page dashboard-page impact-redesign"><section className="dashboard-hero"><div><p className="eyebrow"><span className="live-dot"/> {t(language, 'impact').toUpperCase()}</p><h1>{language === 'en' ? 'See each choice become a ripple.' : language === 'ta' ? 'ஒவ்வொரு தேர்வின் அலைவையும் பாருங்கள்.' : language === 'te' ? 'ప్రతి ఎంపిక ఒక అలగా మారడాన్ని చూడండి.' : 'हर विकल्प को प्रभाव की लहर बनते देखें।'}</h1><p>{language === 'en' ? 'Your actions today scale across the timeframe you select, making one brave step easy to see.' : language === 'ta' ? 'இன்றைய உங்கள் செயல்கள் தேர்ந்த கால அளவில் விரிவடைகின்றன; ஒரு துணிச்சலான படியும் தெளிவாகத் தெரியும்.' : language === 'te' ? 'ఈ రోజు మీ చర్యలు ఎంచుకున్న కాలానికి విస్తరిస్తాయి; ఒక ధైర్యమైన అడుగు స్పష్టంగా కనిపిస్తుంది.' : 'आज की आपकी गतिविधियाँ चुनी गई समयावधि में दिखाई जाती हैं, ताकि एक साहसी कदम भी साफ़ दिखे।'}</p></div><label className="impact-select glass"><span><CalendarDays size={16}/>{t(language, 'timeline')}</span><select value={window} onChange={(event) => setWindow(event.target.value)}><option value="1d">{t(language, 'day')}</option><option value="7d">{t(language, 'week')}</option><option value="30d">{t(language, 'month')}</option><option value="365d">{t(language, 'year')}</option></select></label></section><section className="impact-explainer glass"><Sparkles/><p>{language === 'en' ? `A contribution made today is shown as 1 action for 1 day, 7 actions for 1 week, 30 actions for 30 days and 365 actions for a year. You are viewing ${labels}.` : language === 'ta' ? `இன்று செய்த ஒரு பங்களிப்பு 1 நாளுக்கு 1, 1 வாரத்திற்கு 7, 30 நாட்களுக்கு 30, 1 ஆண்டுக்கு 365 செயல்களாகக் காட்டப்படும். நீங்கள் ${labels} பார்கிறீர்கள்.` : language === 'te' ? `ఈ రోజు చేసిన ఒక సహకారం 1 రోజుకు 1గా, 1 వారానికి 7గా, 30 రోజులకు 30గా, ఒక సంవత్సరానికి 365గా చూపబడుతుంది. మీరు ${labels} చూస్తున్నారు.` : `आज किया गया एक योगदान 1 दिन के लिए 1, 1 सप्ताह के लिए 7, 30 दिनों के लिए 30 और एक वर्ष के लिए 365 गतिविधियों के रूप में दिखाया जाता है। आप ${labels} देख रही हैं।`}</p></section><section className="metric-grid timeline-metrics">{tiles.map(({ icon: Icon, label, value: metricValue, color }, index) => <motion.article className="metric-card glass" key={label} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: index * .05 }}><span className="metric-emoji" style={{ color }}><Icon size={24}/></span><div><strong>{loading ? '—' : IN(metricValue)}</strong><p>{label}</p><small>+{loading ? '—' : IN(metricValue)} {labels}</small></div><span className="metric-glow" style={{ background: color }}/></motion.article>)}</section><section className="chart-grid impact-charts"><ChartCard title={language === 'en' ? 'Impact across every timeframe' : language === 'ta' ? 'ஒவ்வொரு காலஅளவிலும் தாக்கம்' : language === 'te' ? 'ప్రతి కాలవ్యవధిలో ప్రభావం' : 'हर समयावधि में प्रभाव'} subtitle={language === 'en' ? 'Compare your opportunity, learning and mentor actions' : language === 'ta' ? 'வாய்ப்பு, கற்றல், வழிகாட்டி செயல்களை ஒப்பிடுக' : language === 'te' ? 'అవకాశం, అభ్యాసం, మెంటర్ చర్యలను పోల్చండి' : 'अवसर, सीखने और मेंटर गतिविधियों की तुलना करें'} wide><ResponsiveContainer width="100%" height={280}><BarChart data={timeline?.comparisons || []} margin={{ top: 15, left: -14, right: 7 }}><XAxis dataKey="period" tick={{ fontSize: 11, fill: '#765464' }} axisLine={false} tickLine={false}/><YAxis allowDecimals={false} tick={{ fontSize: 11, fill: '#765464' }} axisLine={false} tickLine={false}/><Tooltip contentStyle={tooltipStyle}/><Bar dataKey="opportunities" name={language === 'en' ? 'Opportunities' : language === 'ta' ? 'வாய்ப்புகள்' : language === 'te' ? 'అవకాశాలు' : 'अवसर'} fill="#c74b7c" radius={[7,7,0,0]}/><Bar dataKey="learning" name={language === 'en' ? 'Learning' : language === 'ta' ? 'கற்றல்' : language === 'te' ? 'అభ్యాసం' : 'सीखना'} fill="#7e2146" radius={[7,7,0,0]}/><Bar dataKey="mentoring" name={language === 'en' ? 'Matches' : language === 'ta' ? 'பொருத்தங்கள்' : language === 'te' ? 'సరిపోలికలు' : 'मिलान'} fill="#efc56e" radius={[7,7,0,0]}/></BarChart></ResponsiveContainer></ChartCard><ChartCard title={language === 'en' ? 'What moves the dashboard' : language === 'ta' ? 'டாஷ்போர்டை நகர்த்துவது' : language === 'te' ? 'డాష్‌బోర్డ్‌ను మార్చేవి' : 'डैशबोर्ड को क्या बदलता है'} subtitle={language === 'en' ? 'The action-to-impact connection is visible' : language === 'ta' ? 'செயலுக்கும் தாக்கத்திற்கும் தெளிவான இணைப்பு' : language === 'te' ? 'చర్య, ప్రభావం మధ్య స్పష్టమైన సంబంధం' : 'गतिविधि और प्रभाव का स्पष्ट संबंध'}><div className="impact-rules"><div><BriefcaseBusiness/><span><b>{language === 'en' ? 'Discover an opportunity' : language === 'ta' ? 'வாய்ப்பைக் கண்டறியவும்' : language === 'te' ? 'అవకాశాన్ని కనుగొనండి' : 'अवसर खोजें'}</b><small>+1 {language === 'en' ? 'opportunity today' : language === 'ta' ? 'வாய்ப்பு இன்று' : language === 'te' ? 'అవకాశం ఈ రోజు' : 'अवसर आज'}</small></span></div><div><GraduationCap/><span><b>{language === 'en' ? 'Finish a learning stage' : language === 'ta' ? 'கற்றல் கட்டத்தை முடிக்கவும்' : language === 'te' ? 'అభ్యాస దశను పూర్తి చేయండి' : 'सीखने का चरण पूरा करें'}</b><small>+1 {language === 'en' ? 'learning action today' : language === 'ta' ? 'கற்றல் செயல் இன்று' : language === 'te' ? 'అభ్యాస చర్య ఈ రోజు' : 'सीखने की गतिविधि आज'}</small></span></div><div><MessageCircleHeart/><span><b>{language === 'en' ? 'Request mentor guidance' : language === 'ta' ? 'வழிகாட்டலைக் கோருங்கள்' : language === 'te' ? 'మెంటర్ మార్గదర్శకత్వాన్ని అభ్యర్థించండి' : 'मेंटर मार्गदर्शन का अनुरोध करें'}</b><small>+1 {language === 'en' ? 'match today' : language === 'ta' ? 'பொருத்தம் இன்று' : language === 'te' ? 'సరిపోలిక ఈ రోజు' : 'मिलान आज'}</small></span></div></div></ChartCard></section></div>
}

function ImpactDashboard({ metrics, language }) {
  return <><ImpactDashboardCore metrics={metrics} language={language}/><ImpactShowcaseGraphs metrics={metrics} language={language}/></>
}

function ImpactShowcaseGraphs({ metrics, language }) {
  const copy = language === 'ta' ? { title: 'உங்கள் தாக்கத்தின் காட்சி', subtitle: 'ஒவ்வொரு அட்டவணையும் முன்னேற்றத்தை ஒரு கொண்டாட்டமாக மாற்றுகிறது.', radar: 'STEM திறன் சமநிலை', radarSub: 'சமூகத்தின் வளர்ச்சி வலிமைகள்', pulse: 'வாராந்திர முன்னேற்றத் துடிப்பு', pulseSub: 'கற்றல் மற்றும் வாய்ப்பு வேகம்', orbit: 'வாய்ப்பு சுற்றுப்பாதை', orbitSub: 'அடுத்த வாய்ப்புக்கான உங்கள் தயார்நிலை' } : language === 'te' ? { title: 'మీ ప్రభావ దృశ్యం', subtitle: 'ప్రతి చార్ట్ పురోగతిని వేడుకగా మారుస్తుంది.', radar: 'STEM నైపుణ్య సమతుల్యత', radarSub: 'సంఘం ఎదుగుదల బలాలు', pulse: 'వారపు పురోగతి పల్స్', pulseSub: 'అభ్యాసం, అవకాశం వేగం', orbit: 'అవకాశ కక్ష్య', orbitSub: 'తదుపరి అవకాశానికి మీ సిద్ధత' } : language === 'hi' ? { title: 'आपके प्रभाव का दृश्य', subtitle: 'हर चार्ट प्रगति को उत्सव में बदलता है।', radar: 'STEM कौशल संतुलन', radarSub: 'समुदाय की उभरती ताकतें', pulse: 'साप्ताहिक प्रगति की धड़कन', pulseSub: 'सीखने और अवसर की गति', orbit: 'अवसर कक्षा', orbitSub: 'अगले अवसर के लिए आपकी तैयारी' } : { title: 'Your impact, in full colour.', subtitle: 'Every chart turns progress into something worth celebrating.', radar: 'STEM strength balance', radarSub: 'The community’s growing strengths', pulse: 'Weekly momentum pulse', pulseSub: 'Learning and opportunity velocity', orbit: 'Opportunity orbit', orbitSub: 'Your readiness for the next opening' }
  const strength = [{ skill: 'Curiosity', value: 92 }, { skill: 'Learning', value: 84 }, { skill: 'Progress', value: 76 }, { skill: 'Community', value: 88 }, { skill: 'Action', value: 81 }]
  const pulse = [{ day: 'Mon', learning: 18, opportunity: 9 }, { day: 'Tue', learning: 27, opportunity: 13 }, { day: 'Wed', learning: 23, opportunity: 19 }, { day: 'Thu', learning: 38, opportunity: 22 }, { day: 'Fri', learning: 31, opportunity: 28 }, { day: 'Sat', learning: 46, opportunity: 34 }, { day: 'Sun', learning: 54, opportunity: 41 }]
  const orbit = [{ name: language === 'en' ? 'Exploring' : language === 'ta' ? 'ஆராய்வு' : language === 'te' ? 'అన్వేషణ' : 'खोज', value: 38 }, { name: language === 'en' ? 'Building' : language === 'ta' ? 'உருவாக்கம்' : language === 'te' ? 'నిర్మాణం' : 'निर्माण', value: 31 }, { name: language === 'en' ? 'Matching' : language === 'ta' ? 'பொருத்தம்' : language === 'te' ? 'సరిపోలిక' : 'मिलान', value: 22 }, { name: language === 'en' ? 'Celebrating' : language === 'ta' ? 'கொண்டாட்டம்' : language === 'te' ? 'సెలబ్రేషన్' : 'उत्सव', value: 9 }]
  return <section className="page dashboard-page impact-showcase"><div className="showcase-heading"><div><p className="eyebrow"><Sparkles size={14}/> {language === 'en' ? 'THE VISUAL IMPACT STUDIO' : language === 'ta' ? 'காட்சி தாக்க மையம்' : language === 'te' ? 'విజువల్ ఇంపాక్ట్ స్టూడియో' : 'विजुअल इम्पैक्ट स्टूडियो'}</p><h2>{copy.title}</h2><p>{copy.subtitle}</p></div><div className="showcase-total glass"><Sparkles/><strong>{IN((metrics.roadmaps || 0) + (metrics.matches || 0))}</strong><span>{language === 'en' ? 'collective next steps' : language === 'ta' ? 'ஒருங்கிணைந்த அடுத்த படிகள்' : language === 'te' ? 'సామూహిక తదుపరి అడుగులు' : 'सामूहिक अगले कदम'}</span></div></div><div className="showcase-grid"><ChartCard title={copy.radar} subtitle={copy.radarSub}><ResponsiveContainer width="100%" height={285}><RadarChart data={strength} outerRadius="71%"><PolarGrid stroke="#e7cbd5"/><PolarAngleAxis dataKey="skill" tick={{ fontSize: 11, fill: '#765464' }}/><Radar dataKey="value" stroke="#8b2349" fill="#c74b7c" fillOpacity={.45}/><Tooltip contentStyle={tooltipStyle}/></RadarChart></ResponsiveContainer></ChartCard><ChartCard title={copy.pulse} subtitle={copy.pulseSub}><ResponsiveContainer width="100%" height={285}><AreaChart data={pulse} margin={{ top: 15, left: -14, right: 8 }}><defs><linearGradient id="pulseLearning" x1="0" x2="0" y1="0" y2="1"><stop stopColor="#8b2349" stopOpacity=".55"/><stop offset="1" stopColor="#8b2349" stopOpacity="0"/></linearGradient><linearGradient id="pulseOpportunity" x1="0" x2="0" y1="0" y2="1"><stop stopColor="#efc56e" stopOpacity=".55"/><stop offset="1" stopColor="#efc56e" stopOpacity="0"/></linearGradient></defs><XAxis dataKey="day" tick={{ fontSize: 11, fill: '#765464' }} axisLine={false} tickLine={false}/><YAxis tick={{ fontSize: 10, fill: '#765464' }} axisLine={false} tickLine={false}/><Tooltip contentStyle={tooltipStyle}/><Area type="monotone" dataKey="learning" stroke="#8b2349" strokeWidth={3} fill="url(#pulseLearning)"/><Area type="monotone" dataKey="opportunity" stroke="#efae35" strokeWidth={3} fill="url(#pulseOpportunity)"/></AreaChart></ResponsiveContainer></ChartCard><ChartCard title={copy.orbit} subtitle={copy.orbitSub}><div className="orbit-chart"><ResponsiveContainer width="100%" height={235}><PieChart><Pie data={orbit} dataKey="value" nameKey="name" innerRadius={58} outerRadius={92} paddingAngle={5}>{orbit.map((entry, index) => <Cell fill={['#7e2146','#c74b7c','#efc56e','#8b6477'][index]} key={entry.name}/>)}</Pie><Tooltip contentStyle={tooltipStyle}/></PieChart></ResponsiveContainer><div className="orbit-centre"><Sparkles/><b>{Math.round(((metrics.roadmaps || 0) + (metrics.matches || 0)) / 100)}</b><span>{language === 'en' ? 'spark' : language === 'ta' ? 'ஒளி' : language === 'te' ? 'కాంతి' : 'चमक'}</span></div></div><div className="chart-key orbit-key">{orbit.map((item, index) => <span key={item.name}><i style={{ background: ['#7e2146','#c74b7c','#efc56e','#8b6477'][index] }}/>{item.name}</span>)}</div></ChartCard></div></section>
}

