function PoliciesPage({ language = 'en' }) {
  const [query, setQuery] = useState('')
  const [activeCategory, setActiveCategory] = useState('all')
  const [selectedPolicy, setSelectedPolicy] = useState(null)
  const filteredPolicies = useMemo(() => {
    const needle = query.trim().toLocaleLowerCase()
    return policyCatalog.filter((policy) => {
      const categoryMatches = activeCategory === 'all' || policy.category === activeCategory
      const searchText = [policy.title, policy.summary, policy.who, policy.impact, policy.lane, policy.type].join(' ').toLocaleLowerCase()
      return categoryMatches && (!needle || searchText.includes(needle))
    })
  }, [activeCategory, query])
  useEffect(() => {
    if (!selectedPolicy) return undefined
    const closeOnEscape = (event) => event.key === 'Escape' && setSelectedPolicy(null)
    document.addEventListener('keydown', closeOnEscape)
    return () => document.removeEventListener('keydown', closeOnEscape)
  }, [selectedPolicy])
  const resetFilters = () => { setQuery(''); setActiveCategory('all') }
  const localized = (value) => copyFor(value, language)
  const locale = policyLocale[language] || policyLocale.en
  return <div className={`page policy-page locale-${language}`}>
    <section className="policy-hero glass">
      <div className="policy-hero-copy"><span className="badge"><Landmark size={14}/> {localized('POLICY LIBRARY · INDIA')}</span><h1>{localized('Know the support already built for her.')}</h1><p>{localized('A plain-language guide to programmes that can help women and girls learn, research, build, return and lead.')}</p><label className="policy-search"><Search size={18}/><span className="sr-only">{localized('Search policies')}</span><input aria-label={localized('Search policies')} value={query} onChange={(event) => setQuery(event.target.value)} placeholder={localized('Search by programme, stage or support…')}/></label></div>
      <div className="policy-hero-aside"><div className="policy-orbit-mark"><Landmark size={29}/><span>20</span><small>{locale.programmes}</small></div><div className="policy-hero-stats"><span><b>3</b> {locale.pathways}</span><span><b>20</b> {locale.linked}</span><span><b>1</b> {locale.starting}</span></div></div>
    </section>
    <section className="policy-filter-area" aria-label={localized('Policy filters')}><div className="policy-section-heading"><div><p className="eyebrow">{localized('FIND YOUR LANE')}</p><h2>{localized('Support that meets the moment')}</h2></div><p>{localized('Browse by the kind of next step you are ready to take.')}</p></div><div className="policy-filter-row">{policyCategories.map(({ key, label, short, icon: Icon }) => <button type="button" key={key} className={`policy-filter ${activeCategory === key ? 'active' : ''}`} aria-pressed={activeCategory === key} onClick={() => setActiveCategory(key)}><span className="policy-filter-icon"><Icon size={17}/></span><span><b>{localized(label)}</b><small>{key === 'all' ? policyCount(policyCatalog.length, language) : `${policyCount(policyCatalog.filter((policy) => policy.category === key).length, language)} · ${localized(short)}`}</small></span></button>)}</div></section>
    <section className="policy-results" aria-live="polite"><div className="policy-results-head"><div><p className="eyebrow">{localized(query ? 'SEARCH RESULTS' : 'THE LIBRARY')}</p><h2>{filteredPolicies.length} {filteredPolicies.length === 1 ? localized('programme') : localized('programmes')} {localized('to explore')}</h2></div>{query && <button className="text-button policy-clear" type="button" onClick={resetFilters}>{localized('Clear search')} <X size={15}/></button>}</div>{filteredPolicies.length > 0 ? <div className="policy-grid">{filteredPolicies.map((policy, index) => <PolicyCard key={policy.id} policy={policy} index={index} language={language} onOpen={() => setSelectedPolicy(policy)}/>)}</div> : <div className="policy-empty glass"><Search size={24}/><h3>{localized('No policy matched that search.')}</h3><p>{localized('Try a programme name, “scholarship”, “research”, “training” or “enterprise”.')}</p><button type="button" className="button ghost" onClick={resetFilters}><span>{localized('Show all programmes')}</span><RefreshCcw size={16}/></button></div>}</section>
    <section className="policy-guide glass"><div className="policy-guide-icon"><ShieldCheck size={23}/></div><div><p className="eyebrow">{localized('A KIND, IMPORTANT CHECK')}</p><h2>{localized('Use this as a starting point, not a promise.')}</h2><p>{localized('Eligibility, dates, funding, reservation and application routes can change. Always confirm the current details on the linked official portal or with your state, district or institution.')}</p></div><div className="policy-guide-points"><span><CheckCircle2 size={15}/> {localized('Plain-language summaries')}</span><span><CheckCircle2 size={15}/> {localized('Official-source links')}</span><span><CheckCircle2 size={15}/> {localized('Verify before applying cues')}</span></div></section>
    {selectedPolicy && <PolicyDetail policy={selectedPolicy} language={language} onClose={() => setSelectedPolicy(null)}/>} 
  </div>
}

function PolicyCard({ policy, index, language = 'en', onOpen }) {
  const Icon = policy.category === 'education' ? GraduationCap : policy.category === 'stem' ? FlaskConical : BriefcaseBusiness
  const localized = (value) => copyFor(value, language)
  return <motion.article className={`policy-card glass policy-${policy.category}`} initial={{ opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: Math.min(index * .035, .35) }}><div className="policy-card-top"><span className="policy-number">{String(index + 1).padStart(2, '0')}</span><span className="policy-type"><Icon size={13}/>{localized(policy.type)}</span></div><span className="policy-lane">{localized(policy.lane)}</span><h3>{localized(policy.title)}</h3><p className="policy-summary">{localized(policy.summary)}</p><div className="policy-facts"><span><Users size={14}/><b>{localized('Who it can help')}</b>{localized(policy.who)}</span><span><Target size={14}/><b>{localized('What it can unlock')}</b>{localized(policy.impact)}</span></div><footer className="policy-card-footer"><a className="policy-source" href={policy.sourceUrl} target="_blank" rel="noreferrer"><ExternalLink size={14}/>{localized('Official source')}</a><button type="button" className="policy-details-button" onClick={onOpen}>{localized('View details')} <ArrowRight size={15}/></button></footer></motion.article>
}

function PolicyDetail({ policy, language = 'en', onClose }) {
  const localized = (value) => copyFor(value, language)
  return <div className="policy-modal-backdrop" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onClose()}><section className="policy-modal glass" role="dialog" aria-modal="true" aria-labelledby={`policy-dialog-${policy.id}`} onMouseDown={(event) => event.stopPropagation()}><button type="button" className="policy-modal-close" aria-label={localized('Close policy details')} onClick={onClose} autoFocus><X size={19}/></button><div className="policy-modal-heading"><span className="badge"><Landmark size={13}/> {localized(policy.type)}</span><span className="policy-lane">{localized(policy.lane)}</span><h2 id={`policy-dialog-${policy.id}`}>{localized(policy.title)}</h2><p>{localized(policy.summary)}</p></div><div className="policy-detail-grid"><div><p className="eyebrow">{localized('WHO IT CAN HELP')}</p><p>{localized(policy.who)}</p></div><div><p className="eyebrow">{localized('WHAT IT CAN UNLOCK')}</p><p>{localized(policy.impact)}</p></div></div><div className="policy-verify"><ShieldCheck size={18}/><div><b>{localized('Before you apply')}</b><p>{localized(policy.verify)}</p></div></div><div className="policy-modal-actions"><a className="button primary" href={policy.sourceUrl} target="_blank" rel="noreferrer"><span>{localized('Open official source')}</span><ExternalLink size={16}/></a><button type="button" className="button ghost" onClick={onClose}><span>{localized('Back to library')}</span><ChevronLeft size={16}/></button></div></section></div>
}

function ChartCard({ title, subtitle, children, wide = false }) { return <article className={`chart-card glass ${wide?'wide':''}`}><div className="chart-title"><div><h3>{title}</h3><p>{subtitle}</p></div><span><BarChart3 size={17}/></span></div>{children}</article> }
const tooltipStyle = {border: '1px solid rgba(126,33,70,.15)', borderRadius: 12, background: '#fffafb', boxShadow: '0 10px 30px rgba(77,24,48,.1)', fontSize: 12}

export default App
